let lang=localStorage.getItem('portfolio-lang')||'en',awardFilter='all';const $=s=>document.querySelector(s);
function trophy(){return '<svg viewBox="0 0 64 64" aria-hidden="true"><path fill="currentColor" d="M20 8h24v8h10v8c0 9.2-5.4 15.6-14.1 17.8C38 45 35.3 47 32 48.2V54h10v6H22v-6h10v-5.8c-3.3-1.2-6-3.2-7.9-6.4C15.4 39.6 10 33.2 10 24v-8h10V8Zm0 14h-4v2c0 5.2 2.5 9.2 7.1 11.1A28.8 28.8 0 0 1 20 22Zm24 0a28.8 28.8 0 0 1-3.1 13.1C45.5 33.2 48 29.2 48 24v-2h-4Z"/></svg>'}
function medal(){return '<svg viewBox="0 0 64 64" aria-hidden="true"><path fill="currentColor" d="M18 4h12l2 22-10 8L18 4Zm28 0H34l-2 22 10 8 4-30Z" opacity=".68"/><circle cx="32" cy="40" r="17" fill="currentColor"/><circle cx="32" cy="40" r="10" fill="white" opacity=".35"/></svg>'}
function ribbon(){return '<svg viewBox="0 0 64 64" aria-hidden="true"><circle cx="32" cy="24" r="17" fill="currentColor"/><path fill="currentColor" d="m21 38-4 22 15-9 15 9-4-22a23 23 0 0 1-22 0Z" opacity=".8"/><path fill="white" opacity=".65" d="m32 13 3.2 6.5 7.2 1-5.2 5.1 1.2 7.2-6.4-3.4-6.4 3.4 1.2-7.2-5.2-5.1 7.2-1L32 13Z"/></svg>'}
function badge(){return '<svg viewBox="0 0 64 64" aria-hidden="true"><path fill="currentColor" d="M32 4 40 12l11-1 2 11 7 10-7 10-2 11-11-1-8 8-8-8-11 1-2-11-7-10 7-10 2-11 11 1 8-8Z"/><text x="32" y="37" text-anchor="middle" font-size="15" font-weight="900" fill="white">TOP</text></svg>'}
function iconType(type){if(type==='trophy-gold')return['gold',trophy()];if(type==='trophy-silver')return['silver',trophy()];if(type==='trophy-bronze')return['bronze',trophy()];if(type==='medal-gold')return['gold',medal()];if(type==='medal-silver')return['silver',medal()];if(type==='medal-bronze')return['bronze',medal()];if(type==='top')return['top',badge()];return['honour',ribbon()]}
function typeLabel(type){const map={en:{'trophy-gold':'1st Place','trophy-silver':'2nd Place','trophy-bronze':'3rd Place','medal-gold':'Gold Medal / Award','medal-silver':'Silver Medal / Award','medal-bronze':'Bronze Medal','honour':'Honour / Mention','finalist':'Finalist','top':'Top 10'},id:{'trophy-gold':'Juara 1','trophy-silver':'Juara 2','trophy-bronze':'Juara 3','medal-gold':'Medali / Award Emas','medal-silver':'Medali / Award Perak','medal-bronze':'Medali Perunggu','honour':'Honour / Harapan','finalist':'Finalis','top':'Top 10'}};return map[lang][type]||map[lang].honour}
const statusLabels={en:{completed:'Completed',ongoing:'Ongoing',draft:'Draft',planned:'Planned',presented:'Presented',published:'Published',review:'Under Review',manuscript:'Manuscript Complete'},id:{completed:'Selesai',ongoing:'Berlangsung',draft:'Draft',planned:'Direncanakan',presented:'Dipresentasikan',published:'Terbit',review:'Dalam Review',manuscript:'Manuskrip Selesai'}};
function statusBadge(key){return '<span class="status status-'+key+'">'+statusLabels[lang][key]+'</span>'}
function periodStatus(period){return /Present|Sekarang/i.test(period)?'ongoing':'completed'}
let theme=localStorage.getItem('portfolio-theme')||((window.matchMedia&&window.matchMedia('(prefers-color-scheme: dark)').matches)?'dark':'light');
function applyTheme(){document.documentElement.dataset.theme=theme;const el=document.getElementById('themeIcon');if(el)el.textContent=theme==='dark'?'☀':'◐'}
function researchCard(r){return '<article class="card research-card '+(r.status==='draft'?'featured':'')+'"><div class="card-status-row"><div class="kicker">'+r.year+' · '+r.venue+'</div>'+statusBadge(r.status)+'</div><h4>'+r.title+'</h4><p><strong>'+r.authors+'</strong></p><p style="margin-top:10px">'+r.description[lang]+'</p><div class="research-meta">'+r.tags.map(t=>'<span class="tag">'+t+'</span>').join('')+'</div><div class="pub-meta"><div><strong>'+ui[lang].publicationLink+'</strong><span>'+(r.publication?'<a href="'+r.publication+'" target="_blank" rel="noreferrer">Open ↗</a>':ui[lang].pending)+'</span></div><div><strong>'+ui[lang].doi+'</strong><span>'+(r.doi?r.doi:ui[lang].pending)+'</span></div></div>'+(r.conference?'<div class="link-row"><a class="btn btn-secondary" href="'+r.conference+'" target="_blank" rel="noreferrer">'+ui[lang].conferencePage+' ↗</a></div>':'')+(r.note?'<div class="research-note">'+r.note[lang]+'</div>':'')+'</article>'}
function academicWorkCard(w){return '<article class="card book-card"><div class="book-cover"><small>INEQUALITY</small><strong>PROBLEM SOLVING<br>BOOK</strong><span>2026</span></div><div><div class="card-status-row"><div class="kicker">'+w.year+' · '+(lang==='en'?'Book & Intellectual Property':'Buku & Kekayaan Intelektual')+'</div><div style="display:flex;gap:7px;flex-wrap:wrap">'+statusBadge(w.status)+statusBadge(w.secondaryStatus)+'</div></div><h4>'+w.title+'</h4><p><strong>'+w.subtitle[lang]+'</strong></p><p style="margin-top:7px">'+w.authors+'</p><p style="margin-top:12px">'+w.description[lang]+'</p><div class="tags">'+w.tags.map(t=>'<span class="tag">'+t+'</span>').join('')+'</div><div class="research-note">'+w.statusNote[lang]+'</div></div></article>'}
function nav(){const ids=['about','research','projects','experience','achievements','skills','contact'],items=ui[lang].nav.map((x,i)=>'<a href="#'+ids[i]+'">'+x+'</a>').join('');$('#desktopNav').innerHTML=items;$('#mobileMenu').innerHTML=items}
function bullets(arr){return '<ul class="detail-list">'+arr.map(x=>'<li>'+x+'</li>').join('')+'</ul>'}
function timeline(items){return '<div class="timeline">'+items.map(x=>'<article class="timeline-item"><time>'+x.period+'</time><div><div class="item-topline"><h4>'+x.role+'</h4>'+statusBadge(x.status||periodStatus(x.period))+'</div><div class="org">'+x.org+(x.place?' · '+x.place:'')+'</div>'+bullets(x.bullets[lang])+'</div></article>').join('')+'</div>'}
function awardHTML(a){const [cls,svg]=iconType(a.type);return '<article class="award-card" data-year="'+a.year+'"><div class="award-icon '+cls+'">'+svg+'</div><div><h4>'+a.title+'</h4><p>'+a.org+' · '+a.date+'</p><span class="award-type">'+typeLabel(a.type)+'</span></div></article>'}
function projectCard(p){return '<article class="card project-card" data-project="'+p.id+'" tabindex="0" role="button"><div class="card-status-row"><div class="kicker">'+p.category+' · '+p.year+'</div>'+statusBadge(p.status||(p.id==='graph-labeling'?'presented':'completed'))+'</div><h4>'+p.title+'</h4><p>'+p.summary[lang]+'</p><div class="tags">'+p.tools.slice(0,4).map(t=>'<span class="tag">'+t+'</span>').join('')+'</div><div class="project-result">'+ui[lang].showDetails+' →</div></article>'}
function render(){nav();$('#langLabel').textContent=lang==='en'?'ID':'EN';$('#footerTagline').textContent=lang==='en'?'Mathematics · Research · Education':'Matematika · Riset · Pendidikan';document.documentElement.lang=lang;const u=ui[lang];
$('#app').innerHTML='<section class="hero anchor" id="home"><div class="container hero-grid"><div><div class="eyebrow">'+u.heroEyebrow+'</div><h1>Desca Affajry Rais</h1><h2>'+u.heroTitle+'</h2><p>'+u.heroText+'</p><div class="hero-actions"><a class="btn btn-primary" href="#research">'+u.explore+' →</a><a class="btn btn-secondary" href="#projects">'+u.viewProjects+'</a><a class="btn btn-secondary" href="'+profile.linkedin+'" target="_blank" rel="noreferrer">LinkedIn</a></div><div class="hero-meta"><span><i class="dot"></i> Universitas Diponegoro · Mathematics</span><span><i class="dot"></i> GPA 3.92 / 4.00</span><span><i class="dot"></i> '+profile.location[lang]+'</span></div></div><div class="portrait"><div class="monogram">DAR</div></div></div></section>'
+'<section class="section anchor" id="about"><div class="container intro-grid"><div><div class="eyebrow">'+u.about+'</div><h3 class="section-title">'+u.aboutTitle+'</h3></div><div class="intro-copy">'+profile.summary[lang].map(p=>'<p>'+p+'</p>').join('')+'<div class="stat-grid"><div class="stat"><strong>3.92</strong><span>GPA / 4.00</span></div><div class="stat"><strong>29</strong><span>'+(lang==='en'?'CV awards listed':'prestasi di CV')+'</span></div><div class="stat"><strong>2026</strong><span>1st Place · ON-MIPA UNDIP</span></div><div class="stat"><strong>590</strong><span>TOEFL ITP Prediction</span></div></div></div></div><div class="container subsection"><h4>'+u.education+'</h4>'+education.map(e=>'<article class="edu-card"><time>'+e.period+'</time><div><h4>'+e.school+'</h4><p><strong>'+e.degree[lang]+'</strong> · '+e.place+'</p>'+bullets(e.details[lang])+'</div></article>').join('')+'</div></section>'
+'<section class="section alt anchor" id="research"><div class="container"><div class="head"><div><div class="eyebrow">'+u.research+'</div><h3>'+u.research+'</h3></div><p>'+u.researchDesc+'</p></div><div class="grid">'+publications.map(p=>'<article class="card publication-card"><div class="kicker">'+p.year+' · '+p.role[lang]+'</div><h4>'+p.title+'</h4><p>'+p.description[lang]+'</p><div class="pub-meta"><div><strong>'+u.publicationLink+'</strong><span>'+(p.publication?'<a href="'+p.publication+'" target="_blank">Open ↗</a>':u.pending)+'</span></div><div><strong>'+u.doi+'</strong><span>'+(p.doi?'<a href="https://doi.org/'+p.doi+'" target="_blank">'+p.doi+'</a>':u.pending)+'</span></div></div><div class="link-row"><a class="btn btn-secondary" href="'+p.conference+'" target="_blank" rel="noreferrer">'+u.conferencePage+' ↗</a></div><div class="tags"><span class="tag">Graph Theory</span><span class="tag">Combinatorics</span><span class="tag">Modular Labeling</span><span class="tag">Proof Writing</span></div></article><article class="card"><div class="kicker">'+(lang==='en'?'Research Interests':'Minat Riset')+'</div><h4>'+(lang==='en'?'Pure Mathematics & Foundational Structures':'Matematika Murni & Struktur Fundamental')+'</h4><p>'+(lang==='en'?'Real Analysis, Complex Analysis, Abstract Algebra, Topology, Combinatorics, Graph Theory, and rigorous proof-oriented mathematics.':'Analisis Real, Analisis Kompleks, Struktur Aljabar, Topologi, Kombinatorika, Teori Graf, dan matematika berorientasi pembuktian rigor.')+'</p></article>').join('')+'</div></div></section>'
+'<section class="section anchor" id="projects"><div class="container"><div class="head"><div><div class="eyebrow">'+u.projects+'</div><h3>'+u.projects+'</h3></div><p>'+u.projectsDesc+'</p></div><div class="grid">'+projects.map(projectCard).join('')+'</div></div></section>'
+'<section class="section alt anchor" id="experience"><div class="container"><div class="head"><div><div class="eyebrow">'+u.experience+'</div><h3>'+u.experience+'</h3></div><p>'+(lang==='en'?'Complete work history and academic-facing professional roles from the CV and current profile.':'Riwayat kerja lengkap dan peran profesional-akademik dari CV serta profil terbaru.')+'</p></div>'+timeline(professionalExperience)+'<div class="subsection"><h4>'+u.organization+'</h4>'+timeline(organizationExperience)+'</div><div class="subsection"><h4>'+u.committee+'</h4><div class="compact-list">'+committees.map(c=>'<div class="compact-item"><strong>'+c[1]+' · '+c[2]+'</strong><span>'+c[3]+' · '+c[0]+'</span></div>').join('')+'</div></div><div class="subsection"><h4>'+u.training+'</h4><div class="grid-2">'+training.map(t=>'<article class="card"><div class="kicker">'+t.period+'</div><h4>'+t.name+'</h4><p><strong>'+t.org+'</strong></p><p style="margin-top:8px">'+t.desc[lang]+'</p></article>').join('')+'</div></div><div class="subsection"><h4>'+u.certs+'</h4><div class="compact-list">'+certifications.map(c=>'<div class="compact-item"><strong>'+c[0]+'</strong><span>'+[c[1],c[2]].filter(Boolean).join(' · ')+'</span></div>').join('')+'</div></div></div></section>'
+'<section class="section anchor" id="achievements"><div class="container"><div class="head"><div><div class="eyebrow">'+u.achievements+'</div><h3>'+u.achievements+'</h3></div><p>'+u.achievementsDesc+'</p></div><div class="award-toolbar"><button class="filter-btn '+(awardFilter==='all'?'active':'')+'" data-filter="all">'+u.all+'</button><button class="filter-btn '+(awardFilter==='2026'?'active':'')+'" data-filter="2026">2026</button><button class="filter-btn '+(awardFilter==='2025'?'active':'')+'" data-filter="2025">2025</button><button class="filter-btn '+(awardFilter==='earlier'?'active':'')+'" data-filter="earlier">'+u.other+'</button></div><div class="awards-grid">'+achievements.filter(a=>awardFilter==='all'||String(a.year)===awardFilter||(awardFilter==='earlier'&&a.year<2025)).map(awardHTML).join('')+'</div></div></section>'
+'<section class="section dark anchor" id="skills"><div class="container"><div class="head"><div><div class="eyebrow" style="color:var(--cyan)">'+u.skills+'</div><h3>'+u.skills+'</h3></div><p>'+(lang==='en'?'Mathematics is the common thread connecting my research, teaching, olympiad work, and computational projects.':'Matematika menjadi benang merah yang menghubungkan riset, pengajaran, olimpiade, dan proyek komputasional saya.')+'</p></div><div class="areas">'+[...skills.math,...skills.technical,...skills.data,...skills.academic].map(x=>'<span class="area">'+x+'</span>').join('')+'</div><div class="subsection"><h4 style="color:white">'+u.languages+'</h4><div class="areas"><span class="area">'+u.indonesian+'</span><span class="area">'+u.english+'</span></div></div></div></section>'
+'<section class="section anchor" id="contact"><div class="container contact-grid"><div><div class="eyebrow">'+u.contact+'</div><h3 class="section-title">'+u.contactTitle+'</h3><p style="color:var(--muted);max-width:620px">'+u.contactDesc+'</p><div class="hero-actions"><a class="btn btn-primary" href="mailto:'+profile.email+'">'+u.email+'</a><a class="btn btn-secondary" href="'+profile.linkedin+'" target="_blank" rel="noreferrer">LinkedIn</a><a class="btn btn-secondary" href="'+profile.github+'" target="_blank" rel="noreferrer">GitHub</a></div></div><div class="contact-card"><div class="contact-row"><span>'+u.email+'</span><a href="mailto:'+profile.email+'">'+profile.email+'</a></div><div class="contact-row"><span>'+u.phone+'</span><a href="tel:'+profile.phone.replace(/\s/g,'')+'">'+profile.phone+'</a></div><div class="contact-row"><span>'+u.linkedin+'</span><a href="'+profile.linkedin+'" target="_blank">descaaffajryrais</a></div><div class="contact-row"><span>'+u.github+'</span><a href="'+profile.github+'" target="_blank">DescaAR</a></div><div class="contact-row"><span>'+u.location+'</span><strong>'+profile.location[lang]+'</strong></div></div></div></section>';bind()}
function bind(){document.querySelectorAll('.project-card').forEach(el=>{const open=()=>openProject(el.dataset.project);el.addEventListener('click',open);el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();open()}})});document.querySelectorAll('.filter-btn').forEach(b=>b.addEventListener('click',()=>{awardFilter=b.dataset.filter;render()}));document.querySelectorAll('#mobileMenu a').forEach(a=>a.addEventListener('click',()=>$('#mobileMenu').classList.remove('open')))}
function openProject(id){const p=projects.find(x=>x.id===id);if(!p)return;const u=ui[lang];$('#modalContent').innerHTML='<div class="kicker">'+p.category+' · '+p.year+'</div><h2 id="modalTitle">'+p.title+'</h2><p>'+p.summary[lang]+'</p><h3>'+u.projectProblem+'</h3><p>'+p.problem[lang]+'</p><h3>'+u.projectApproach+'</h3>'+bullets(p.approach[lang])+'<h3>'+u.projectResults+'</h3><div class="result-grid">'+p.results.map(r=>'<div class="result-box"><strong>'+r[0]+'</strong><span>'+r[1][lang]+'</span></div>').join('')+'</div><h3>'+u.projectTools+'</h3><div class="tags">'+p.tools.map(t=>'<span class="tag">'+t+'</span>').join('')+'</div>'+(p.note?'<h3>'+u.projectNote+'</h3><div class="note">'+p.note[lang]+'</div>':'')+'<div class="link-row">'+(p.github?'<a class="btn btn-primary" href="'+p.github+'" target="_blank" rel="noreferrer">'+u.visitRepo+' ↗</a>':'')+(p.conference?'<a class="btn btn-secondary" href="'+p.conference+'" target="_blank" rel="noreferrer">'+u.visitConference+' ↗</a>':'')+'</div>';$('#modalBackdrop').classList.add('open');$('#modalBackdrop').setAttribute('aria-hidden','false');document.body.classList.add('modal-open');history.replaceState(null,'','#project-'+id)}
function closeModal(){$('#modalBackdrop').classList.remove('open');$('#modalBackdrop').setAttribute('aria-hidden','true');document.body.classList.remove('modal-open');if(location.hash.startsWith('#project-'))history.replaceState(null,'','#projects')}
$('#langToggle').addEventListener('click',()=>{lang=lang==='en'?'id':'en';localStorage.setItem('portfolio-lang',lang);render()});$('#mobileToggle').addEventListener('click',()=>$('#mobileMenu').classList.toggle('open'));$('#modalClose').addEventListener('click',closeModal);$('#modalBackdrop').addEventListener('click',e=>{if(e.target===$('#modalBackdrop'))closeModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});document.getElementById('year').textContent=new Date().getFullYear();render();if(location.hash.startsWith('#project-'))setTimeout(()=>openProject(location.hash.replace('#project-','')),50);